import{_ as s,o as a,c as t,a2 as i}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Day 14: Autotools & CMake Build Systems","description":"","frontmatter":{},"headers":[],"relativePath":"day14-autotools-and-cmake-build-systems.md","filePath":"day14-autotools-and-cmake-build-systems.md"}'),o={name:"day14-autotools-and-cmake-build-systems.md"};function l(n,e,d,r,c,h){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="day-14-autotools-cmake-build-systems" tabindex="-1">Day 14: Autotools &amp; CMake Build Systems <a class="header-anchor" href="#day-14-autotools-cmake-build-systems" aria-label="Permalink to &quot;Day 14: Autotools &amp; CMake Build Systems&quot;">​</a></h1><div style="background:linear-gradient(135deg, #11998e 0%, #38ef7d 100%);padding:1.5rem;border-radius:12px;margin-bottom:2rem;color:white;"><p><strong>🎯 Learning Objectives</strong></p><p>By the end of this module, you will be able to:</p><ol><li>Understand how Yocto abstracts complex build systems (Autotools, CMake, Meson)</li><li>Use <code>inherit autotools</code> and <code>inherit cmake</code> in your recipes</li><li>Pass custom configuration flags to the underlying build system</li><li>Troubleshoot common cross-compilation configuration failures</li></ol></div><div class="info custom-block"><p class="custom-block-title">PREREQUISITES</p><ul><li>Completed <a href="/day13-recipe-dependencies-depends-rdepends.html">Day 13: Recipe Dependencies (DEPENDS &amp; RDEPENDS)</a></li></ul></div><hr><h2 id="_1-the-build-system-abstraction" tabindex="-1">1. The Build System Abstraction <a class="header-anchor" href="#_1-the-build-system-abstraction" aria-label="Permalink to &quot;1. The Build System Abstraction&quot;">​</a></h2><p>In Day 8 and Day 9, you wrote raw <code>do_compile</code> and <code>do_install</code> tasks to execute compiler strings or <code>make</code> manually.</p><p>In the real world of open-source software, projects use sophisticated build systems (like Autotools or CMake) that probe the host environment, generate complex Makefiles, and handle installation paths automatically.</p><p>Writing manual <code>do_compile</code> functions for these projects in Yocto would be a nightmare. Instead, Yocto provides <strong>Classes</strong> that abstract away the entire process.</p><hr><h2 id="_2-autotools-inherit-autotools" tabindex="-1">2. Autotools (<code>inherit autotools</code>) <a class="header-anchor" href="#_2-autotools-inherit-autotools" aria-label="Permalink to &quot;2. Autotools (\`inherit autotools\`)&quot;">​</a></h2><p>The GNU Build System (Autotools) is the standard for legacy open-source C/C++ projects. You know a project uses Autotools if the source code contains a <code>configure.ac</code> script and requires you to run <code>./configure &amp;&amp; make &amp;&amp; make install</code>.</p><p>To compile an Autotools project in Yocto, you only need one line of code:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SUMMARY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;An Autotools based application&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SRC_URI</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;...&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># This automatically writes the do_configure, do_compile, and do_install tasks!</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">inherit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> autotools</span></span></code></pre></div><h3 id="passing-custom-flags" tabindex="-1">Passing Custom Flags <a class="header-anchor" href="#passing-custom-flags" aria-label="Permalink to &quot;Passing Custom Flags&quot;">​</a></h3><p>Usually, you need to enable or disable specific features during the <code>./configure</code> stage. You do this using the <code>EXTRA_OECONF</code> variable.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Translates to: ./configure --enable-gui --disable-debug</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">EXTRA_OECONF</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;--enable-gui --disable-debug&quot;</span></span></code></pre></div><h3 id="dealing-with-broken-autotools-autotools-brokensep" tabindex="-1">Dealing with Broken Autotools (<code>autotools-brokensep</code>) <a class="header-anchor" href="#dealing-with-broken-autotools-autotools-brokensep" aria-label="Permalink to &quot;Dealing with Broken Autotools (\`autotools-brokensep\`)&quot;">​</a></h3><p>Standard Autotools creates a separate build directory outside the source tree to keep the source clean (Out-of-tree builds). Sometimes, poorly written <code>configure.ac</code> scripts break if they aren&#39;t executed directly inside the source tree.</p><p>If your Autotools recipe fails during <code>do_configure</code> with strange &quot;file not found&quot; errors, try switching to the fallback class:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">inherit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> autotools-brokensep</span></span></code></pre></div><hr><h2 id="_3-cmake-inherit-cmake" tabindex="-1">3. CMake (<code>inherit cmake</code>) <a class="header-anchor" href="#_3-cmake-inherit-cmake" aria-label="Permalink to &quot;3. CMake (\`inherit cmake\`)&quot;">​</a></h2><p>CMake is the modern standard for C/C++ projects. It uses <code>CMakeLists.txt</code> files to define the build logic.</p><p>Just like Autotools, Yocto completely abstracts CMake compilation:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SUMMARY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;A modern CMake based application&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SRC_URI</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;...&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># This automatically runs \`cmake\`, \`make\`, and \`make install\`</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">inherit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cmake</span></span></code></pre></div><h3 id="passing-custom-cmake-definitions" tabindex="-1">Passing Custom CMake Definitions <a class="header-anchor" href="#passing-custom-cmake-definitions" aria-label="Permalink to &quot;Passing Custom CMake Definitions&quot;">​</a></h3><p>Instead of <code>./configure</code> flags, CMake uses definitions passed via <code>-D</code>. In Yocto, you pass these using the <code>EXTRA_OECMAKE</code> variable.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Translates to: cmake -DBUILD_TESTS=OFF -DWITH_SSL=ON ...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">EXTRA_OECMAKE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;-DBUILD_TESTS=OFF -DWITH_SSL=ON&quot;</span></span></code></pre></div><hr><h2 id="_4-other-build-systems" tabindex="-1">4. Other Build Systems <a class="header-anchor" href="#_4-other-build-systems" aria-label="Permalink to &quot;4. Other Build Systems&quot;">​</a></h2><p>Yocto supports almost every major build system out of the box via inheritance:</p><ul><li><code>inherit meson</code>: For projects using the Meson build system (ninja).</li><li><code>inherit python3targetconfig</code>: For Python applications (<code>setup.py</code>).</li><li><code>inherit cargo</code>: For Rust applications.</li><li><code>inherit go</code>: For Golang applications.</li></ul><p>By using these classes, Yocto automatically handles all the grueling cross-compilation environment variables, library search paths, and staging directories.</p><hr><h2 id="_5-hands-on-lab-exercises" tabindex="-1">5. Hands-On Lab Exercises <a class="header-anchor" href="#_5-hands-on-lab-exercises" aria-label="Permalink to &quot;5. Hands-On Lab Exercises&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">LAB 14.1: Convert a Recipe to CMake</p><p>Assume you have a <code>helloworld</code> project that uses CMake instead of a raw Makefile.</p><ol><li>Create a <code>CMakeLists.txt</code> in your source directory:<div class="language-cmake vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cmake</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">cmake_minimum_required</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">VERSION</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 3.10)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">project</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(HelloWorld)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">add_executable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(helloworld helloworld.c)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">install</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(TARGETS helloworld DESTINATION bin)</span></span></code></pre></div></li><li>Update your <code>helloworld_1.0.bb</code> recipe. Remove the custom <code>do_compile</code> and <code>do_install</code> blocks entirely.</li><li>Add <code>inherit cmake</code> to the recipe.</li><li>Run <code>bitbake -c clean helloworld &amp;&amp; bitbake helloworld</code>.</li><li>Verify the compilation succeeds and the binary is packaged!</li></ol></div><hr><h2 id="_6-further-reading" tabindex="-1">6. Further Reading <a class="header-anchor" href="#_6-further-reading" aria-label="Permalink to &quot;6. Further Reading&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>URL</th></tr></thead><tbody><tr><td>Autotools Class Reference</td><td><a href="https://docs.yoctoproject.org/ref-manual/classes.html#autotools-bbclass" target="_blank" rel="noreferrer">docs.yoctoproject.org/ref-manual/classes.html#autotools-bbclass</a></td></tr><tr><td>CMake Class Reference</td><td><a href="https://docs.yoctoproject.org/ref-manual/classes.html#cmake-bbclass" target="_blank" rel="noreferrer">docs.yoctoproject.org/ref-manual/classes.html#cmake-bbclass</a></td></tr></tbody></table><hr><div style="display:flex;justify-content:space-between;margin-top:2rem;padding-top:1rem;border-top:1px solid #e2e8f0;"><a href="/day13-recipe-dependencies-depends-rdepends">← Day 13: Recipe Dependencies</a><a href="/day15-cmake-recipes-and-devshell-debugging">Day 15: Devshell Debugging →</a></div>`,41)])])}const k=s(o,[["render",l]]);export{u as __pageData,k as default};
